function openForm(type,existing=null){$('#dialog-title').textContent=existing?`Editar ${LABELS[type].toLowerCase()}`:`Nuevo ${LABELS[type].toLowerCase()}`;$('#dialog-kicker').textContent=LABELS[type].toUpperCase();$('#dialog-fields').innerHTML=formMarkup(type,{...(existing?.data||{}),...(existing?{_recordId:existing.recordId}:{})});const f=$('#record-form');formSubmit=async values=>{let data={...values};if(['school','course','division','subject','cutoff','subgroup'].includes(type))data.name=String(values.name||'').trim();if(type==='schedule'){data.dayOfWeek=Number(values.dayOfWeek);data.startTime=String(values.startTime||'');data.endTime=String(values.endTime||'');if(!data.schoolId||!data.subjectId||!data.courseId||!data.divisionId||!Number.isInteger(data.dayOfWeek)||!data.startTime||!data.endTime||data.startTime>=data.endTime)throw Error('Completá el grupo, día y una franja horaria válida.');const duplicate=live('schedule').find(x=>x.id!==existing?.id&&x.data.schoolId===data.schoolId&&x.data.subjectId===data.subjectId&&x.data.courseId===data.courseId&&x.data.divisionId===data.divisionId&&x.data.dayOfWeek===data.dayOfWeek&&x.data.startTime===data.startTime);if(duplicate)throw Error('Ya existe ese horario para el grupo.');const overlap=live('schedule').some(x=>x.id!==existing?.id&&x.data.schoolId===data.schoolId&&x.data.subjectId===data.subjectId&&x.data.courseId===data.courseId&&x.data.divisionId===data.divisionId&&Number(x.data.dayOfWeek)===data.dayOfWeek&&data.startTime<x.data.endTime&&x.data.startTime<data.endTime);if(overlap)throw Error('El horario se superpone con otra sesión de esta materia y grupo.');data.id=existing?.id||uuid();}if(type==='student'){data.fullName=String(values.fullName||'').trim();data.studentId=String(values.studentId||'').trim();if(!data.fullName||!data.studentId||data.studentId.length>80||/[\u0000-\u001f\u007f]/.test(data.studentId))throw Error('Completá nombre e ID válido (máximo 80 caracteres).');const duplicate=live('student').find(x=>x.data.studentId===data.studentId&&x.id!==existing?.id);if(duplicate)throw Error('Ya existe un estudiante con ese ID. Editá la ficha existente.');}if(type==='scale'){const min=Number(values.min),max=Number(values.max),intervals=String(values.intervalsText||'').split(/\n/).filter(Boolean).map(line=>{const m=line.trim().match(/^(.+?):\s*(-?\d+)\s*-\s*(-?\d+)$/);if(!m)throw Error('Formato de equivalencia: Desaprobado: 1-6.');return{label:m[1].trim(),min:Number(m[2]),max:Number(m[3])};});data={name:String(values.name||'').trim(),min,max,mode:values.mode,intervals};scaleValid(data);}if(type==='membership'){data.subgroupIds=[...f.elements.subgroupIds.selectedOptions].map(x=>x.value).filter(Boolean);data.studentId=existing?.data.studentId||f.dataset.studentId;if(!data.studentId)throw Error('Falta el estudiante de esta pertenencia.');const dup=live('membership').some(x=>x.id!==existing?.id&&x.data.studentId===data.studentId&&x.data.schoolId===data.schoolId&&x.data.subjectId===data.subjectId&&x.data.courseId===data.courseId&&x.data.divisionId===data.divisionId);if(dup)throw Error('Esta pertenencia ya está cargada.');}if(type==='attendance'){data.studentId=String(values.studentId||'');data.date=String(values.date||'');data.status=String(values.status||'present');if(!data.studentId||!data.date||!['present','absent'].includes(data.status))throw Error('Elegí Presente o Ausente antes de guardar la asistencia.');}if(type==='observation'||type==='topic'){const f=selected();Object.assign(data,{schoolId:existing?.data.schoolId||f.school,subjectId:existing?.data.subjectId||f.subject,courseId:existing?.data.courseId||f.course,divisionId:existing?.data.divisionId||f.division});if(!data.date||!data.schoolId||!data.subjectId||!data.courseId||!data.divisionId||!String(data.text||data.topic||'').trim())throw Error('Completá el grupo, la fecha y el contenido.');if(type==='topic'&&!String(data.activity||'').trim())throw Error('Completá la actividad realizada.');if(type==='observation'){data.text=String(data.text||'').trim();data.title=String(data.title||'').trim();data.studentId=String(data.studentId||'');data.studentName=data.studentId?getOne('student',data.studentId)?.data.fullName||'':'';}else{data.topic=String(data.topic||'').trim();data.activity=String(data.activity||'').trim();}}if(type==='grade'){data.studentId=String(values.studentId||'');data.assessmentId=String(values.assessmentId||'');data.status=String(values.status||'pending');data.value=['pending','absent','not_submitted','exempt'].includes(data.status)?'':values.value;const att=findAttendance(String(values.studentId||''),String(values.attendanceId||''));data.attendanceId=String(values.attendanceId||'');data.gradeDate=att?.data.date||existing?.data.gradeDate||getOne('assessment',String(values.assessmentId||''))?.data.date||'';data.observation=String(values.observation||'');data.studentName=getOne('student',data.studentId)?.data.fullName||'';data.qualitative=getOne('scale',getOne('assessment',data.assessmentId)?.data.scaleId)?.data.mode==='qualitative';if(!data.studentId||!data.assessmentId)throw Error('Elegí estudiante e instancia.');if(data.status==='graded'){if(!att||att.data.status!=='present')throw Error('Elegí una fecha con asistencia Presente para cargar la calificación.');const a=getOne('assessment',data.assessmentId);if(!a)throw Error('No se encuentra la instancia.');numericValue(data,displayScale(a));}}let weightPlan=[];if(type==='assessment'){data.subgroupIds=[...f.elements.subgroupIds.selectedOptions].map(x=>x.value).filter(Boolean);data.weightLocked=String(values.weight||'').trim()!=='';data.weight=data.weightLocked?Number(values.weight):0;if(!data.name||!data.date||!data.schoolId||!data.subjectId||!data.courseId||!data.divisionId||!data.cutoffId||!data.scaleId)throw Error('Completá la instancia, la fecha de evaluación y su contexto.');const group=live('assessment').filter(x=>x.data.subjectId===data.subjectId&&x.data.cutoffId===data.cutoffId&&x.id!==existing?.id).map(x=>({id:x.id,weight:Number(x.data.weight||0),weightLocked:!!x.data.weightLocked})),proposal={id:existing?.id||uuid(),weight:data.weight,weightLocked:data.weightLocked};weightPlan=allocate([...group,proposal]);const assigned=weightPlan.find(x=>x.id===proposal.id);data.weight=assigned.weight;data.weightLocked=assigned.weightLocked;}const old=existing||(type==='grade'?records.find(x=>x.type==='grade'&&x.data.studentId===data.studentId&&x.data.assessmentId===data.assessmentId):type==='schedule'?{id:data.id}:null)||{};if(type==='grade'&&!old.id)old.id=Gradebook.gradeKey(data.studentId,data.assessmentId);const r=record(type,data,old);await persist(r);if(type==='assessment'){for(const x of weightPlan){const item=getOne('assessment',x.id);if(item&&(item.data.weight!==x.weight||item.data.weightLocked!==x.weightLocked)){await saveRecord({...item,data:{...item.data,weight:x.weight,weightLocked:x.weightLocked}});}}{const members=live('membership').filter(m=>m.data.schoolId===data.schoolId&&m.data.subjectId===data.subjectId&&m.data.courseId===data.courseId&&m.data.divisionId===data.divisionId&&(!data.subgroupIds.length||(m.data.subgroupIds||[]).some(x=>data.subgroupIds.includes(x)))),ids=[...new Set(members.map(m=>m.data.studentId))];for(const studentId of ids){const student=live('student').find(x=>x.id===studentId);if(!student)continue;const gid=Gradebook.gradeKey(student.id,r.id);if(records.some(x=>x.type==='grade'&&x.id===gid))continue;await persist(record('grade',{studentId:student.id,studentName:student.data.fullName,assessmentId:r.id,value:'',status:'pending',qualitative:getOne('scale',data.scaleId)?.data.mode==='qualitative',gradeDate:data.date||new Date().toISOString().slice(0,10),observation:''},{id:gid}));}}}render();};$('#record-dialog').showModal();}
$('#record-form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;try{const f=e.currentTarget;if(!formSubmit)return;const fd=new FormData(f),values=Object.fromEntries(fd.entries());if(f.elements.subgroupIds)values.subgroupIds=[...f.elements.subgroupIds.selectedOptions].map(x=>x.value).filter(Boolean);await formSubmit(values);$('#record-dialog').close();toast('Guardado en Sheets.');}catch(err){if(err.message==='DATA_CONFLICT'){toast('El registro cambió en Sheets. Actualizá y volvé a aplicar tu cambio.','error');await loadRemote().catch(()=>{});}else toast(err.message||'No se pudo guardar en Sheets.','error');}finally{if(submit)submit.disabled=false;}});
