$('#grade-assessment').onchange=renderGradeEntry;$('#save-grade-session').onclick=async e=>{const button=e.currentTarget,a=getOne('assessment',$('#grade-assessment').value);if(!a){toast('Elegí una instancia.','error');return;}const cards=$$('#grade-entry-list [data-student]'),changes=[];for(const card of cards){const student=getOne('student',card.dataset.student),old=gradeFor(student.id,a.id),status=card.querySelector('[data-entry-status]').value,value=card.querySelector('[data-entry-value]').value,attendanceId=card.querySelector('[data-entry-attendance]').value,att=findAttendance(student.id,attendanceId),scale=displayScale(a);if(status==='graded'&&!att){toast(`Elegí una fecha con asistencia Presente para ${student.data.fullName}.`,'error');return;}const finalValue=['pending','absent','not_submitted','exempt'].includes(status)?'':value;if(status==='pending'&&!old&&!String(value||'').trim())continue;const data={studentId:student.id,studentName:student.data.fullName,assessmentId:a.id,status,value:finalValue,qualitative:scale.mode==='qualitative',gradeDate:att?.data.date||old?.data.gradeDate||a.data.date,observation:old?.data.observation||'',...(status==='graded'?{attendanceId}:{})};if(status==='graded')try{numericValue(data,scale);}catch(err){toast(`${student.data.fullName}: ${err.message}`,'error');return;}const unchanged=old&&['status','value','attendanceId','gradeDate'].every(k=>String(old.data[k]??'')===String(data[k]??''));if(!unchanged)changes.push(record('grade',data,{...(old||{}),id:old?.id||Gradebook.gradeKey(student.id,a.id)}));}if(!changes.length){toast('No hay cambios en las notas.');return;}if(changes.length>100){toast('El grupo supera el límite de 100 notas por guardado.','error');return;}button.disabled=true;try{await saveRecords(changes);renderGradeEntry();renderGradebook();toast(`Notas guardadas: ${changes.length} estudiante(s).`);}catch(err){toast('No se pudo guardar el lote de notas: '+err.message,'error');await loadRemote().catch(()=>{});}finally{button.disabled=false;}};
