$('#save-attendance-session').onclick=async e=>{const button=e.currentTarget,f=selected(),schedule=scheduleForDate(attendanceDate,$('#attendance-schedule').value);if(!schedule){toast('Elegí una sesión de esta materia que coincida con la fecha.','error');return;}const students=sessionRoster(schedule),cards=$$('#attendance-list [data-attendance-student]'),changes=students.filter((st,i)=>Boolean(cards[i]?.dataset.draft)).map((st,i)=>{const card=$('#attendance-list [data-attendance-student="'+CSS.escape(st.id)+'"]'),old=attendanceForDate(st.id,attendanceDate,f,schedule.id),data={studentId:st.id,date:attendanceDate,scheduleId:schedule.id,status:card.dataset.draft,schoolId:f.school,subjectId:f.subject,courseId:f.course,divisionId:f.division};return record('attendance',data,{...(old||{}),id:old?.id||Gradebook.attendanceKey(st.id,attendanceDate,schedule.id)});});if(!changes.length){toast('Marcá Presente o elegí Marcar ausente para al menos un estudiante.','error');return;}if(changes.length>100){toast('El grupo supera el máximo de 100 registros por guardado; no se escribió ningún cambio.','error');return;}button.disabled=true;try{await saveRecords(changes);renderAttendance();renderGradebook();toast(`Asistencia guardada: ${changes.length} cambio(s).`);}catch(err){toast(err.message==='ATTENDANCE_HAS_GRADED_RECORD'?'No se puede quitar Presente: ya hay una calificación vinculada.':'No se pudo guardar la sesión: '+err.message,'error');await loadRemote().catch(()=>{});}finally{button.disabled=false;}};
$('#attendance-list').addEventListener('change',e=>{if(e.target.matches('[data-attendance-status]')){const card=e.target.closest('.data-card');card.dataset.draft=e.target.checked?'present':card.dataset.status==='absent'?'absent':'';card.querySelector('[data-mark-absent]').disabled=card.dataset.draft==='absent';card.querySelector('small').textContent=card.dataset.draft==='present'?'Se guardará Presente':card.dataset.draft==='absent'?'Se guardará Ausente':'Sin cargar';}});


$$('.tab').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.tab==='admin')loadTrash().catch(e=>toast('No se pudo cargar la papelera: '+e.message,'error'));}));

$('#assessment-cards').addEventListener('change',async e=>{const id=e.target.dataset.weight;if(!id)return;try{const group=assessmentsFor().map(x=>({id:x.id,weight:Number(x.data.weight||0),weightLocked:!!x.data.weightLocked})),next=allocate(group.map(x=>x.id===id?{...x,weight:e.target.value===''?0:Number(e.target.value),weightLocked:e.target.value!==''}:x));for(const x of next){const old=getOne('assessment',x.id);if(old&&(old.data.weight!==x.weight||old.data.weightLocked!==x.weightLocked))await saveRecord({...old,data:{...old.data,weight:x.weight,weightLocked:x.weightLocked}});}render();toast('Pesos actualizados en Sheets.');}catch(err){toast('No se pudieron guardar los pesos: '+err.message,'error');await loadRemote().catch(()=>{});}});
$('#equal-weights').onclick=async()=>{try{const list=assessmentsFor(),next=equalWeights(list.map(x=>({id:x.id,weight:x.data.weight,weightLocked:false}))),changes=next.map(x=>{const old=getOne('assessment',x.id);return {...old,data:{...old.data,weight:x.weight,weightLocked:false}};});await saveRecords(changes);render();toast('Pesos guardados en Sheets.');}catch(err){toast('No se pudieron guardar los pesos: '+err.message,'error');await loadRemote().catch(()=>{});}};
$('#filter-student').oninput=renderGradebook;['school','subject','course','division','cutoff','subgroup'].forEach(k=>$(`#filter-${k}`).onchange=render);$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===b));$$('.tab-view').forEach(x=>x.hidden=x.id!==`view-${b.dataset.tab}`);});
function validateRecord(r){if(!TYPES.includes(r.type)||!r.id||!r.recordId.endsWith(`::${r.id}`)||!r.data||typeof r.data!=='object')throw Error(`Registro inválido: ${r.recordId}`);try{Gradebook.validateRecord(r);}catch(e){throw Error(e.message==='INVALID_STUDENT'?'Completá nombre e ID válido de cada estudiante antes de guardar.':'Revisá el registro '+r.id+'.');}if(r.type==='student'&&(!r.data.studentId||!r.data.fullName))throw Error('Completá nombre e ID de cada estudiante antes de guardar.');if(r.type==='grade'){if(!r.data.studentId||!r.data.assessmentId||!Object.hasOwn(STATUSES,r.data.status))throw Error('Calificación incompleta.');if(r.data.status==='graded'){const a=getOne('assessment',r.data.assessmentId),s=a&&getOne('scale',a.data.scaleId);if(!s)throw Error('La escala de esta instancia no está disponible.');numericValue(r.data,s.data);}}if(r.type==='scale')scaleValid(r.data);}
$('#refresh').onclick=()=>loadRemote();
function importRowRecord(row,index){let data;try{data=JSON.parse(row.DatosJSON);}catch(_){throw Error(`Fila ${index}: DatosJSON debe ser JSON válido.`);}const type=String(row.Tipo||''),id=String(row.ID||''),recordId=`${type}::${id}`,existing=records.find(x=>x.recordId===recordId);if(!type||!id)throw Error(`Fila ${index}: completá Tipo e ID.`);const version=Number(row.Version||0);if(!Number.isInteger(version)||version<0)throw Error(`Fila ${index}: Version debe ser un entero ≥ 0.`);const item={recordId,type,id,data,expectedVersion:version,syncState:'synced',updatedAt:new Date().toISOString()};validateRecord(item);return{item,existing,index};}
function importWorkbook(file){return file.arrayBuffer().then(buffer=>{const book=XLSX.read(buffer,{type:'array'}),sheet=book.Sheets.Registros;if(!sheet)throw Error('El archivo necesita una pestaña Registros. La pestaña Libreta exportada es solo de lectura.');const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:true});const parsed=rows.map((row,i)=>importRowRecord(row,i+2));const seen=new Set();for(const x of parsed){if(seen.has(x.item.recordId))throw Error(`ID duplicado en archivo: ${x.item.recordId}`);seen.add(x.item.recordId);}const candidates=parsed.map(x=>({...x,status:!x.existing?'create':JSON.stringify(x.existing.data)===JSON.stringify(x.item.data)?'same':x.existing.expectedVersion!==x.item.expectedVersion?'conflict':'update'}));$('#import-summary').textContent=`${candidates.filter(x=>x.status==='create').length} altas · ${candidates.filter(x=>x.status==='update').length} actualizaciones · ${candidates.filter(x=>x.status==='conflict').length} conflictos · ${candidates.filter(x=>x.status==='same').length} sin cambios. Los cambios se escribirán en Sheets al confirmar.`;$('#import-rows').innerHTML=candidates.map((x,i)=>`<tr><td>${x.index}</td><td>${esc(LABELS[x.item.type])} · ${esc(x.item.id)}</td><td>${x.status==='create'?'Alta':x.status==='same'?'Sin cambios':x.status==='update'?'Cambios contra la versión de Sheets':'Versión distinta a Sheets; comparar'}${x.existing?`<details><summary>Comparar actual y archivo</summary><pre>Actual:\n${esc(JSON.stringify(x.existing.data,null,2))}\nArchivo:\n${esc(JSON.stringify(x.item.data,null,2))}</pre></details>`:''}</td><td><select data-import="${i}"><option value="file">Usar el archivo</option><option value="keep">Conservar actual</option><option value="skip">Cancelar fila</option></select><details><summary>Corregir registro antes de importar</summary><textarea data-import-json="${i}" rows="4">${esc(JSON.stringify(x.item.data,null,2))}</textarea></details></td></tr>`).join('')||'<tr><td colspan="4" class="empty">La planilla está vacía.</td></tr>';importCandidates=candidates;$('#import-dialog').showModal();}).catch(err=>toast(err.message||'No pude leer el Excel.','error'));}
$('#export-xlsx').onclick=()=>{if(!sessionToken){toast('Iniciá sesión para exportar datos de Sheets.','error');return;}const book=XLSX.utils.book_new(),rows=records.filter(r=>!r.deletedAt).map(r=>({Tipo:r.type,ID:r.id,Version:Number(r.expectedVersion||0),Estado:r.syncState,DatosJSON:JSON.stringify(r.data)}));XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),'Registros');const students=roster(),assessments=assessmentsFor(),wide=students.map(student=>{const row={Estudiante:student.data.fullName,ID:student.data.studentId};for(const a of assessments){const g=gradeFor(student.id,a.id);row[a.data.name]=g?`${g.data.value??''} · ${STATUSES[g.data.status]}`:'';}return row;});XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(wide),'Libreta');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Instrucciones'],['Registros: esquema normalizado, una fila por entidad. Editá aquí para importar.'],['Libreta: vista ancha generada para lectura; no se importa como esquema.'],['Los cambios se guardan directamente en Sheets al confirmarlos.'],['La ausencia de filas no borra datos.']]),'Instrucciones');XLSX.writeFile(book,'registro-notas.xlsx');};
$('#import-xlsx').onclick=()=>$('#xlsx-file').click();$('#xlsx-file').onchange=e=>{const file=e.target.files?.[0];e.target.value='';if(file){if(!sessionToken){toast('Iniciá sesión para importar en Sheets.','error');return;}loadRemote().then(()=>importWorkbook(file)).catch(()=>{});}};$$('[data-import-close]').forEach(button=>button.onclick=()=>$('#import-dialog').close());$('#import-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const changes=[];for(let i=0;i<importCandidates.length;i++){const choice=$(`[data-import="${i}"]`).value,x=importCandidates[i];if(choice==='keep'||choice==='skip')continue;try{const data=JSON.parse($(`[data-import-json="${i}"]`).value),r={...x.item,data,expectedVersion:Number(x.existing?.expectedVersion||0),syncState:'synced',updatedAt:new Date().toISOString()};validateRecord(r);changes.push(r);}catch(err){toast(`Fila ${x.index}: ${err.message||'contenido inválido'}`,'error');return;}}if(!confirm(`¿Guardar ${changes.length} registro(s) directamente en Sheets?`))return;try{await saveRecords(changes);$('#import-dialog').close();render();toast(`${changes.length} registro(s) sincronizados con Sheets.`);}catch(err){await loadRemote().catch(()=>{});toast('No se completó toda la importación en Sheets: '+err.message,'error');}finally{if(submit)submit.disabled=false;}};
window.addEventListener('online',()=>{if(sessionToken)loadRemote().catch(()=>{});});window.addEventListener('offline',()=>{$('#connection').textContent='Sin conexión a Sheets';$('#connection').className='connection offline';});
(async()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});$('#connection').textContent='Iniciá sesión para conectar con Sheets';$('#connection').className='connection offline';if(sessionToken){try{await loadRemote();}catch(_){}}})();
